class ReplayDisposition(str,Enum): APPLIED='APPLIED';DUPLICATE_IGNORED='DUPLICATE_IGNORED'
class CheckpointDisposition(str,Enum): RESTORED='RESTORED';REJECT_VERSION='REJECT_VERSION';REJECT_FIXTURE='REJECT_FIXTURE';REJECT_CONFIG='REJECT_CONFIG';REJECT_INSTANCE='REJECT_INSTANCE';REJECT_HASH='REJECT_HASH';REBUILD_REQUIRED='REBUILD_REQUIRED'
