class BudgetStatus(str,Enum): PASS='PASS';DEGRADED='DEGRADED';BLOCKED='BLOCKED'
class ReleaseProfileId(str,Enum): TRADING_30D='TRADING_30D';AUDIT_90D='AUDIT_90D';PERFORMANCE_7D='PERFORMANCE_7D';SAFE_DIAGNOSTIC='SAFE_DIAGNOSTIC'
